    25→pub unsafe fn syscall0(n: u64) -> u64 {
    26→    let ret: u64;
    27→    unsafe {
    28→        asm!(
    29→            "syscall",
    30→            in("rax") n,
    31→            lateout("rax") ret,
    32→            lateout("rcx") _,
    33→            lateout("r11") _,
    34→            options(nostack)
    35→        );
    36→    }
    37→    ret
    38→}
