   226→fn init_heap() {
   227→    unsafe {
   228→        HEAP_START = brk(core::ptr::null_mut());
   229→        HEAP_END = HEAP_START;
   230→        HEAP_CURRENT = HEAP_START;
   231→    }
   232→}
   233→
   234→#[unsafe(no_mangle)]
   235→pub extern "C" fn malloc(size: usize) -> *mut u8 {
   236→    unsafe {
   237→        let aligned_size = (size + 15) & !15;
   238→        let new_current = HEAP_CURRENT.add(aligned_size);
   239→
   240→        if new_current > HEAP_END {
   241→            let grow_size = (aligned_size + 4095) & !4095;
   242→            let new_end = brk(HEAP_END.add(grow_size));
   243→            if new_end <= HEAP_END {
   244→                return core::ptr::null_mut();
   245→            }
   246→            HEAP_END = new_end;
   247→        }
   248→
   249→        let ptr = HEAP_CURRENT;
   250→        HEAP_CURRENT = new_current;
   251→        ptr
   252→    }
   253→}
   254→
   255→/// Reallocate memory.
   256→///
   257→/// # Safety
   258→/// If `ptr` is non-null, it must have been returned by a previous call to
   259→/// `malloc`, `realloc`, or `calloc`, and `size` must not exceed the original
   260→/// allocation size (this simple allocator doesn't track sizes).
   261→#[unsafe(no_mangle)]
   262→pub unsafe extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
   263→    if ptr.is_null() {
   264→        return malloc(size);
   265→    }
   266→    let new_ptr = malloc(size);
   267→    if !new_ptr.is_null() {
   268→        unsafe {
   269→            core::ptr::copy_nonoverlapping(ptr, new_ptr, size);
   270→        }
   271→    }
   272→    new_ptr
   273→}
   274→
   275→#[unsafe(no_mangle)]
   276→pub extern "C" fn calloc(nmemb: usize, size: usize) -> *mut u8 {
   277→    let total = nmemb.saturating_mul(size);
   278→    let ptr = malloc(total);
   279→    if !ptr.is_null() {
   280→        unsafe {
   281→            core::ptr::write_bytes(ptr, 0, total);
   282→        }
   283→    }
   284→    ptr
   285→}
   286→
   287→#[unsafe(no_mangle)]
   288→pub extern "C" fn free(_ptr: *mut u8) {
   289→    // Simple bump allocator doesn't free individual allocations
   290→}
