   165→#[inline(always)]
   166→pub unsafe fn syscall6(
   167→    n: u64,
   168→    arg1: u64,
   169→    arg2: u64,
   170→    arg3: u64,
   171→    arg4: u64,
   172→    arg5: u64,
   173→    arg6: u64,
