   204→/// Write bytes to a file descriptor.
   205→///
   206→/// # Safety
   207→/// `buf` must point to at least `count` valid bytes.
   208→#[unsafe(no_mangle)]
   209→pub unsafe extern "C" fn write(fd: i32, buf: *const u8, count: usize) -> isize {
   210→    unsafe { syscall3(SYS_WRITE, fd as u64, buf as u64, count as u64) as isize }
   211→}
   212→
   213→/// Read bytes from a file descriptor.
   214→///
   215→/// # Safety
   216→/// `buf` must point to at least `count` bytes of writable memory.
   217→#[unsafe(no_mangle)]
   218→pub unsafe extern "C" fn read(fd: i32, buf: *mut u8, count: usize) -> isize {
