   214→///
   215→/// # Safety
   216→/// `buf` must point to at least `count` bytes of writable memory.
   217→#[unsafe(no_mangle)]
   218→pub unsafe extern "C" fn read(fd: i32, buf: *mut u8, count: usize) -> isize {
