     1→//! Memory allocation (malloc, free, etc.)
     2→
     3→use crate::syscall::{SYS_BRK, syscall1};
     4→
     5→// Heap state
     6→static mut HEAP_START: *mut u8 = core::ptr::null_mut();
     7→static mut HEAP_END: *mut u8 = core::ptr::null_mut();
     8→static mut HEAP_CURRENT: *mut u8 = core::ptr::null_mut();
     9→
    10→fn brk(addr: *mut u8) -> *mut u8 {
    11→    unsafe { syscall1(SYS_BRK, addr as u64) as *mut u8 }
    12→}
    13→
    14→pub fn init_heap() {
    15→    unsafe {
    16→        HEAP_START = brk(core::ptr::null_mut());
    17→        HEAP_END = HEAP_START;
    18→        HEAP_CURRENT = HEAP_START;
    19→    }
    20→}
    21→
    22→#[unsafe(no_mangle)]
    23→pub extern "C" fn malloc(size: usize) -> *mut u8 {
    24→    unsafe {
    25→        let aligned_size = (size + 15) & !15;
    26→        let new_current = HEAP_CURRENT.add(aligned_size);
    27→
    28→        if new_current > HEAP_END {
    29→            let grow_size = (aligned_size + 4095) & !4095;
    30→            let new_end = brk(HEAP_END.add(grow_size));
    31→            if new_end <= HEAP_END {
    32→                crate::io::write(2, b"malloc: brk failed\n".as_ptr(), 19);
    33→                return core::ptr::null_mut();
    34→            }
    35→            HEAP_END = new_end;
    36→        }
    37→
    38→        let ptr = HEAP_CURRENT;
    39→        HEAP_CURRENT = new_current;
    40→        ptr
    41→    }
    42→}
    43→
    44→/// Reallocate memory.
    45→///
    46→/// # Safety
    47→/// If `ptr` is non-null, it must have been returned by a previous call to
    48→/// `malloc`, `realloc`, or `calloc`, and `size` must not exceed the original
    49→/// allocation size (this simple allocator doesn't track sizes).
    50→#[unsafe(no_mangle)]
    51→pub unsafe extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
    52→    if ptr.is_null() {
    53→        return malloc(size);
    54→    }
    55→    let new_ptr = malloc(size);
    56→    if !new_ptr.is_null() {
    57→        unsafe { memcpy(new_ptr, ptr, size) };
    58→    }
    59→    new_ptr
    60→}
    61→
    62→#[unsafe(no_mangle)]
    63→pub extern "C" fn calloc(nmemb: usize, size: usize) -> *mut u8 {
    64→    let total = nmemb.saturating_mul(size);
    65→    let ptr = malloc(total);
    66→    if !ptr.is_null() {
    67→        // SAFETY: ptr points to at least total bytes (just allocated)
    68→        // Use memset directly to avoid compiler optimizing write_bytes -> memset
    69→        unsafe { memset(ptr, 0, total) };
    70→    }
    71→    ptr
    72→}
    73→
    74→#[unsafe(no_mangle)]
    75→pub extern "C" fn free(_ptr: *mut u8) {
    76→    // Bump allocator doesn't free individual allocations
    77→}
    78→
    79→/// Allocate aligned memory.
    80→///
    81→/// # Safety
    82→/// `memptr` must point to valid writable memory for a pointer.
    83→#[unsafe(no_mangle)]
    84→pub unsafe extern "C" fn posix_memalign(
    85→    memptr: *mut *mut u8,
    86→    alignment: usize,
    87→    size: usize,
    88→) -> i32 {
    89→    // Simple implementation: over-allocate and align
    90→    if !alignment.is_power_of_two() || alignment < core::mem::size_of::<*mut u8>() {
    91→        return 22; // EINVAL
    92→    }
    93→    let ptr = malloc(size + alignment);
    94→    if ptr.is_null() {
    95→        return 12; // ENOMEM
    96→    }
    97→    let aligned = ((ptr as usize + alignment - 1) & !(alignment - 1)) as *mut u8;
    98→    unsafe {
    99→        *memptr = aligned;
   100→    }
   101→    0
   102→}
   103→
   104→// Memory operations - must use manual loops, never core::ptr::* which LLVM optimizes to libc calls
   105→
   106→/// Copy memory.
   107→///
   108→/// # Safety
   109→/// `dest` must point to at least `n` bytes of writable memory.
   110→/// `src` must point to at least `n` bytes of readable memory.
   111→/// The memory regions must not overlap.
   112→#[unsafe(no_mangle)]
   113→pub unsafe extern "C" fn memcpy(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
   114→    for i in 0..n {
   115→        unsafe { *dest.add(i) = *src.add(i) };
   116→    }
   117→    dest
   118→}
   119→
   120→/// Copy memory (handles overlapping regions).
   121→///
   122→/// # Safety
   123→/// `dest` must point to at least `n` bytes of writable memory.
   124→/// `src` must point to at least `n` bytes of readable memory.
   125→#[unsafe(no_mangle)]
   126→pub unsafe extern "C" fn memmove(dest: *mut u8, src: *const u8, n: usize) -> *mut u8 {
   127→    if (dest as usize) <= (src as usize) {
   128→        for i in 0..n {
   129→            unsafe { *dest.add(i) = *src.add(i) };
   130→        }
   131→    } else {
   132→        for i in (0..n).rev() {
   133→            unsafe { *dest.add(i) = *src.add(i) };
   134→        }
   135→    }
   136→    dest
   137→}
   138→
   139→/// Fill memory with a constant byte.
   140→///
   141→/// # Safety
   142→/// `dest` must point to at least `n` bytes of writable memory.
   143→#[unsafe(no_mangle)]
   144→pub unsafe extern "C" fn memset(dest: *mut u8, c: i32, n: usize) -> *mut u8 {
   145→    for i in 0..n {
   146→        unsafe { *dest.add(i) = c as u8 };
   147→    }
   148→    dest
   149→}
   150→
   151→/// Compare memory.
   152→///
   153→/// # Safety
   154→/// `s1` and `s2` must each point to at least `n` bytes of readable memory.
   155→#[unsafe(no_mangle)]
   156→pub unsafe extern "C" fn memcmp(s1: *const u8, s2: *const u8, n: usize) -> i32 {
   157→    for i in 0..n {
   158→        let a = unsafe { *s1.add(i) };
   159→        let b = unsafe { *s2.add(i) };
   160→        if a != b {
   161→            return a as i32 - b as i32;
   162→        }
   163→    }
   164→    0
   165→}
   166→
   167→/// Compare memory (BSD variant).
   168→///
   169→/// # Safety
   170→/// `s1` and `s2` must each point to at least `n` bytes of readable memory.
   171→#[unsafe(no_mangle)]
   172→pub unsafe extern "C" fn bcmp(s1: *const u8, s2: *const u8, n: usize) -> i32 {
   173→    unsafe { memcmp(s1, s2, n) }
   174→}
