    15→/// Result of a batch operation on a single crate
    16→pub struct OpResult {
    17→    pub name: String,
    18→    pub success: bool,
    19→    pub message: String,
    20→    pub size: Option<u64>,
    21→}
    22→
    23→/// Build all workspace crates (excluding build tools)
    24→pub fn build_all(
    25→    workspace: &WorkspaceInfo,
    26→    tspec: Option<&str>,
    27→    release: bool,
    28→    strip: bool,
    29→    fail_fast: bool,
    30→) -> Vec<OpResult> {
    31→    let mut results = Vec::new();
    32→
    33→    for member in workspace.buildable_members() {
    34→        println!("=== {} ===", member.name);
    35→
    36→        let result = match build_crate(&member.name, tspec, release) {
    37→            Ok(build_result) => {
    38→                if strip && member.has_binary {
    39→                    if let Err(e) = strip_binary(&build_result.binary_path) {
    40→                        eprintln!("  warning: strip failed: {}", e);
    41→                    }
    42→                }
    43→                let size = binary_size(&build_result.binary_path).ok();
    44→                OpResult {
    45→                    name: member.name.clone(),
    46→                    success: true,
    47→                    message: format!("{}", build_result.binary_path.display()),
    48→                    size,
    49→                }
    50→            }
    51→            Err(e) => OpResult {
    52→                name: member.name.clone(),
    53→                success: false,
    54→                message: e.to_string(),
    55→                size: None,
    56→            },
    57→        };
    58→
    59→        let failed = !result.success;
    60→        results.push(result);
    61→
    62→        if failed && fail_fast {
    63→            break;
    64→        }
    65→    }
    66→
    67→    results
    68→}
    69→
    70→/// Run all app crates sequentially
    71→pub fn run_all(
    72→    workspace: &WorkspaceInfo,
    73→    tspec: Option<&str>,
    74→    release: bool,
    75→    strip: bool,
    76→) -> Vec<OpResult> {
    77→    let mut results = Vec::new();
    78→
    79→    for member in workspace.runnable_members() {
    80→        println!("=== {} ===", member.name);
