use std::path::Path;

use anyhow::Result;

use crate::binary::{binary_size, strip_binary};
use crate::build::build_crate;
use crate::{print_header, print_hline};

/// Result of building a spec
struct SpecResult {
    name: String,
    size: u64,
}

/// Compare multiple specs for a crate
pub fn compare_specs(
    crate_name: &str,
    spec_paths: &[impl AsRef<Path>],
    release: bool,
    strip: bool,
) -> Result<()> {
    println!(
        "Comparing {} builds{}:\n",
        crate_name,
        if strip { " (stripped)" } else { "" }
    );

    let mut results = Vec::new();

    for spec_path in spec_paths {
        let spec_path = spec_path.as_ref();
        let name = spec_path
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .unwrap_or_else(|| spec_path.display().to_string());

        let size = build_spec(crate_name, spec_path, release, strip)?;
        results.push(SpecResult { name, size });
        println!();
    }

    // Sort by size (smallest first)
    results.sort_by_key(|r| r.size);

    print_comparison(&results);

    Ok(())
}

fn build_spec(crate_name: &str, spec_path: &Path, release: bool, strip: bool) -> Result<u64> {
    let spec_str = spec_path.to_string_lossy();
    println!(
        "  {}:",
        spec_path.file_name().unwrap_or_default().to_string_lossy()
    );

    // Build
    let build_result = build_crate(crate_name, Some(&spec_str), release)?;

    // Optionally strip
    if strip {
        strip_binary(&build_result.binary_path)?;
    }

    // Get size
    let size = binary_size(&build_result.binary_path)?;
    println!("    size: {} bytes", format_size(size));

    Ok(size)
}

fn print_comparison(results: &[SpecResult]) {
    let largest_size = results.iter().map(|r| r.size).max().unwrap_or(0);
    let max_name_len = results.iter().map(|r| r.name.len()).max().unwrap_or(4);

    // Format percent change: show reduction with minus sign, baseline as 0.0%
    let fmt_pct = |size: u64| -> String {
        if largest_size == 0 {
            return "   0.0%".to_string();
        }
        let pct = ((largest_size as f64 - size as f64) / largest_size as f64) * 100.0;
        if pct > 0.0 {
            format!("{:>7.1}%", -pct)
        } else {
            "   0.0%".to_string()
        }
    };

    println!();
    print_header!("COMPARE SUMMARY");
    println!(
        "  {:width$}  {:>10}  {:>8}",
        "Spec",
        "Size",
        "Change",
        width = max_name_len
    );
    for result in results {
        println!(
            "  {:width$}  {:>10}  {}",
            result.name,
            format_size(result.size),
            fmt_pct(result.size),
            width = max_name_len
        );
    }
    print_hline!();
    println!();
}

fn format_size(bytes: u64) -> String {
    if bytes >= 1_000_000 {
        format!("{:.1}M", bytes as f64 / 1_000_000.0)
    } else if bytes >= 1_000 {
        format!("{:.1}K", bytes as f64 / 1_000.0)
    } else {
        format!("{}", bytes)
    }
}

//! Batch operations on all workspace crates
//!
//! Provides build_all, run_all, test_all for operating on all workspace members.

use std::os::unix::fs::PermissionsExt;
use std::process::ExitCode;

use crate::binary::{binary_size, strip_binary};
use crate::build::build_crate;
use crate::run::run_binary;
use crate::testing::test_crate;
use crate::workspace::{CrateKind, WorkspaceInfo};
use crate::{print_header, print_hline};

/// Result of a batch operation on a single crate
pub struct OpResult {
    pub name: String,
    pub success: bool,
    pub message: String,
    pub size: Option<u64>,
}

/// Build all workspace crates (excluding build tools)
pub fn build_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.buildable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip && member.has_binary {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                let size = binary_size(&build_result.binary_path).ok();
                OpResult {
                    name: member.name.clone(),
                    success: true,
                    message: format!("{}", build_result.binary_path.display()),
                    size,
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
                size: None,
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            break;
        }
    }

    results
}

/// Run all app crates sequentially
pub fn run_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    strip: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    for member in workspace.runnable_members() {
        println!("=== {} ===", member.name);

        let result = match build_crate(&member.name, tspec, release) {
            Ok(build_result) => {
                if strip {
                    if let Err(e) = strip_binary(&build_result.binary_path) {
                        eprintln!("  warning: strip failed: {}", e);
                    }
                }
                match run_binary(&build_result.binary_path) {
                    Ok(exit_code) => OpResult {
                        name: member.name.clone(),
                        success: true, // We don't treat non-zero exit as failure
                        message: format!("exit code: {}", exit_code),
                        size: None,
                    },
                    Err(e) => OpResult {
                        name: member.name.clone(),
                        success: false,
                        message: format!("run failed: {}", e),
                        size: None,
                    },
                }
            }
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
                size: None,
            },
        };

        results.push(result);
    }

    results
}

/// Test all workspace crates
pub fn test_all(
    workspace: &WorkspaceInfo,
    tspec: Option<&str>,
    release: bool,
    fail_fast: bool,
) -> Vec<OpResult> {
    let mut results = Vec::new();

    // Test regular crates (excluding Test kind which needs special handling)
    for member in workspace.buildable_members() {
        if member.kind == CrateKind::Test {
            continue; // Handle test crates separately
        }

        println!("=== {} ===", member.name);

        let result = match test_crate(&member.name, tspec, release) {
            Ok(()) => OpResult {
                name: member.name.clone(),
                success: true,
                message: "ok".to_string(),
                size: None,
            },
            Err(e) => OpResult {
                name: member.name.clone(),
                success: false,
                message: e.to_string(),
                size: None,
            },
        };

        let failed = !result.success;
        results.push(result);

        if failed && fail_fast {
            return results;
        }
    }

    // Handle test crates (like rlibc-x2-tests) - build and run all test binaries
    for member in workspace.test_members() {
        println!("=== {} ===", member.name);

        // Build the test crate (builds all binaries)
        if let Err(e) = build_crate(&member.name, tspec, release) {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: format!("build failed: {}", e),
                size: None,
            });
            if fail_fast {
                return results;
            }
            continue;
        }

        // Find and run all test binaries in the target directory
        let profile = if release { "release" } else { "debug" };
        let target_dir = workspace.root.join("target").join(profile);

        // Look for binaries that end with "-tests" in the target directory
        let test_binaries: Vec<_> = std::fs::read_dir(&target_dir)
            .into_iter()
            .flatten()
            .filter_map(|e| e.ok())
            .filter(|e| {
                let name = e.file_name().to_string_lossy().to_string();
                let is_file = e.path().is_file();
                let is_test = name.ends_with("-tests");
                let is_executable = e
                    .metadata()
                    .map(|m| m.permissions().mode() & 0o111 != 0)
                    .unwrap_or(false);
                is_file && is_test && is_executable
            })
            .collect();

        if test_binaries.is_empty() {
            results.push(OpResult {
                name: member.name.clone(),
                success: false,
                message: "no test binaries found".to_string(),
                size: None,
            });
            continue;
        }

        for entry in test_binaries {
            let path = entry.path();
            let bin_name = entry.file_name().to_string_lossy().to_string();

            print!("  Running {}... ", bin_name);

            let result = match run_binary(&path) {
                Ok(exit_code) => {
                    if exit_code == 0 {
                        println!("ok");
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: true,
                            message: "ok".to_string(),
                            size: None,
                        }
                    } else {
                        println!("FAILED (exit {})", exit_code);
                        OpResult {
                            name: format!("{}/{}", member.name, bin_name),
                            success: false,
                            message: format!("exit code: {}", exit_code),
                            size: None,
                        }
                    }
                }
                Err(e) => {
                    println!("FAILED");
                    OpResult {
                        name: format!("{}/{}", member.name, bin_name),
                        success: false,
                        message: format!("run failed: {}", e),
                        size: None,
                    }
                }
            };

            let failed = !result.success;
            results.push(result);

            if failed && fail_fast {
                return results;
            }
        }
    }

    results
}

/// Print a summary of operation results (for tests)
pub fn print_test_summary(results: &[OpResult]) -> ExitCode {
    let max_name_len = results
        .iter()
        .map(|r| r.name.len())
        .max()
        .unwrap_or(5)
        .max(5);

    println!();
    print_header!("TEST SUMMARY");
    println!("  {:width$}  Status", "Crate", width = max_name_len);

    let mut passed = 0;
    let mut failed = 0;

    for result in results {
        let status = if result.success {
            passed += 1;
            "[PASS]"
        } else {
            failed += 1;
            "[FAIL]"
        };
        println!("  {:width$}  {status}", result.name, width = max_name_len);
    }

    println!();
    println!("  Test: {} passed, {} failed", passed, failed);
    println!();
    println!("  Note: Run `cargo xt test xt` or `cargo test -p xt` to test xt itself");
    print_hline!();
    println!();

    if failed > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

/// Print a summary for build operations (OK/FAILED)
pub fn print_summary(results: &[OpResult]) -> ExitCode {
    let max_name_len = results
        .iter()
        .map(|r| r.name.len())
        .max()
        .unwrap_or(5)
        .max(5);

    println!();
    print_header!("BUILD SUMMARY");
    println!("  {:width$}  Status    Size", "Crate", width = max_name_len);

    let mut ok_count = 0;
    let mut failed_count = 0;

    for result in results {
        let status = if result.success {
            ok_count += 1;
            "[ OK ]"
        } else {
            failed_count += 1;
            "[FAIL]"
        };
        let size_str = result
            .size
            .map(format_size)
            .unwrap_or_else(|| "--".to_string());
        println!(
            "  {:width$}  {status}  {:>6}",
            result.name,
            size_str,
            width = max_name_len
        );
    }

    println!();
    println!("  Build: {} ok, {} failed", ok_count, failed_count);
    print_hline!();
    println!();

    if failed_count > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

fn format_size(bytes: u64) -> String {
    if bytes >= 1_000_000 {
        format!("{:.1}M", bytes as f64 / 1_000_000.0)
    } else if bytes >= 1_000 {
        format!("{:.1}K", bytes as f64 / 1_000.0)
    } else {
        format!("{}", bytes)
    }
}

/// Print a summary for run operations (shows exit codes, not pass/fail)
pub fn print_run_summary(results: &[OpResult]) -> ExitCode {
    let max_name_len = results
        .iter()
        .map(|r| r.name.len())
        .max()
        .unwrap_or(5)
        .max(5);

    println!();
    print_header!("RUN SUMMARY");
    println!("  {:width$}  Exit", "Crate", width = max_name_len);

    let mut error_count = 0;

    for result in results {
        if result.success {
            // Extract exit code number from message "exit code: X"
            let code = result
                .message
                .strip_prefix("exit code: ")
                .unwrap_or(&result.message);
            println!(
                "  {:width$}  {:>4}",
                result.name,
                code,
                width = max_name_len
            );
        } else {
            error_count += 1;
            println!(
                "  {:width$}  ERROR: {}",
                result.name,
                result.message,
                width = max_name_len
            );
        }
    }

    println!();
    if error_count > 0 {
        println!("  Run: {} error(s)", error_count);
    }
    print_hline!();
    println!();

    if error_count > 0 {
        ExitCode::from(1)
    } else {
        ExitCode::SUCCESS
    }
}

use anyhow::{Context, Result, bail};
use std::fs;
use std::process::Command;

use crate::build::{apply_spec_to_command, generate_build_rs};
use crate::find_paths::{find_crate_dir, find_tspec, find_workspace_root};
use crate::tspec::load_spec;
use crate::types::{CargoParam, LinkerParam, RustcParam};

/// Check if spec requires nightly toolchain
fn requires_nightly(spec: &crate::types::Spec) -> bool {
    let has_build_std = spec
        .rustc
        .iter()
        .any(|p| matches!(p, RustcParam::BuildStd(_)));

    let has_unstable = spec
        .cargo
        .iter()
        .any(|p| matches!(p, CargoParam::Unstable(_)));

    has_build_std || has_unstable
}

/// Test a crate with a spec
pub fn test_crate(crate_name: &str, tspec: Option<&str>, release: bool) -> Result<()> {
    let workspace = find_workspace_root()?;
    let crate_dir = find_crate_dir(&workspace, crate_name)?;
    let tspec_path = find_tspec(&crate_dir, tspec)?;

    // Track if we generated a build.rs
    let build_rs_path = crate_dir.join("build.rs");
    let had_build_rs = build_rs_path.exists();

    // Apply spec if present, otherwise plain cargo test
    let status = if let Some(path) = &tspec_path {
        let spec = load_spec(path)?;
        println!("Testing {} with spec {}", crate_name, path.display());

        // Generate temporary build.rs for linker flags if needed
        let has_linker_args = spec
            .linker
            .iter()
            .any(|p| matches!(p, LinkerParam::Args(_)));
        if has_linker_args && !had_build_rs {
            generate_build_rs(&build_rs_path, crate_name, &spec)?;
        }

        let mut cmd = Command::new("cargo");
        if requires_nightly(&spec) {
            cmd.arg("+nightly");
        }
        cmd.arg("test");
        cmd.arg("-p").arg(crate_name);
        cmd.current_dir(&workspace);

        apply_spec_to_command(&mut cmd, &spec, &workspace, release)?;
        cmd.status().context("failed to run cargo test")?
    } else {
        println!("Testing {} (no tspec)", crate_name);
        let mut cmd = Command::new("cargo");
        cmd.arg("test");
        cmd.arg("-p").arg(crate_name);
        cmd.current_dir(&workspace);
        if release {
            cmd.arg("--release");
        }
        cmd.status().context("failed to run cargo test")?
    };

    // Clean up generated build.rs (only if we created it)
    if !had_build_rs && build_rs_path.exists() {
        let _ = fs::remove_file(&build_rs_path);
    }

    if !status.success() {
        bail!("cargo test failed");
    }

    Ok(())
}

use anyhow::Result;
use clap::Parser;
use std::process::ExitCode;

use xt::all::{build_all, print_run_summary, print_summary, print_test_summary, run_all, test_all};
use xt::binary::strip_binary;
use xt::build::build_crate;
use xt::cli::{Cli, Commands, TspecCommands};
use xt::compare::compare_specs;
use xt::find_paths::{find_crate_dir, find_tspecs, find_workspace_root};
use xt::run::run_binary;
use xt::testing::test_crate;
use xt::workspace::WorkspaceInfo;

fn main() -> ExitCode {
    match run() {
        Ok(code) => code,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::from(1)
        }
    }
}

fn run() -> Result<ExitCode> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Build {
            crate_name,
            tspec,
            release,
            strip,
            fail_fast,
        } => match crate_name {
            None => {
                // Build all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = build_all(&workspace, tspec.as_deref(), release, strip, fail_fast);
                return Ok(print_summary(&results));
            }
            Some(name) => {
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
            }
        },
        Commands::Run {
            crate_name,
            tspec,
            release,
            strip,
        } => match crate_name {
            None => {
                // Run all apps
                let workspace = WorkspaceInfo::discover()?;
                let results = run_all(&workspace, tspec.as_deref(), release, strip);
                return Ok(print_run_summary(&results));
            }
            Some(name) => {
                // Build, optionally strip, then run
                let result = build_crate(&name, tspec.as_deref(), release)?;
                if strip {
                    strip_binary(&result.binary_path)?;
                }
                let exit_code = run_binary(&result.binary_path)?;
                std::process::exit(exit_code);
            }
        },
        Commands::Test {
            crate_name,
            tspec,
            release,
            fail_fast,
        } => match crate_name {
            None => {
                // Test all crates
                let workspace = WorkspaceInfo::discover()?;
                let results = test_all(&workspace, tspec.as_deref(), release, fail_fast);
                return Ok(print_test_summary(&results));
            }
            Some(name) => {
                test_crate(&name, tspec.as_deref(), release)?;
            }
        },
        Commands::Compare {
            crate_name,
            tspec,
            release,
            strip,
        } => {
            let workspace = find_workspace_root()?;
            let crate_dir = find_crate_dir(&workspace, &crate_name)?;
            let spec_paths = find_tspecs(&crate_dir, &tspec)?;
            compare_specs(&crate_name, &spec_paths, release, strip)?;
        }
        Commands::Compat { crate_name, spec } => {
            match spec {
                Some(s) => println!("compat add: crate={crate_name} spec={s}"),
                None => println!("compat show: crate={crate_name}"),
            }
            // TODO: implement
        }
        Commands::Incompat { crate_name, spec } => {
            println!("incompat add: crate={crate_name} spec={spec}");
            // TODO: implement
        }
        Commands::Tspec { command } => {
            match command {
                TspecCommands::List { crate_name } => {
                    xt::tspec_cmd::list_tspecs(crate_name.as_deref())?;
                }
                TspecCommands::Show { crate_name, tspec } => {
                    println!("ts show: crate={crate_name} tspec={tspec:?}");
                    // TODO: implement
                }
                TspecCommands::Hash { crate_name, tspec } => {
                    println!("ts hash: crate={crate_name} tspec={tspec:?}");
                    // TODO: implement
                }
            }
        }
    }

    Ok(ExitCode::SUCCESS)
}

